/* Host entry of the lifted PC game: load the lifted modules (rt_modules_gen.c, generated by
   build_pc_runtime.py), resolve imports, run the DllMain of the start-up DLLs and the game's entry.

   Usage: me_pc <game Binaries folder> <deps folder: CRT DLLs, rebased/ copies> [user folder]
   The user folder (default "pc-user") receives everything the game writes. */
#include "rt.h"

#include <stdio.h>
#include <string.h>

void rt_kernel32_register(void);
void rt_sync_register(void);
void rt_files_register(void);
void rt_user32_register(void);
void rt_d3d9_register(void);
void rt_physx_support_register(void);
void rt_dinput_register(void);
void rt_fs_init(const char *game, const char *user);

int main(int argc, char **argv)
{
    if (argc < 3) {
        fprintf(stderr, "usage: %s <game Binaries folder> <deps folder> [user folder]\n", argv[0]);
        return 2;
    }
    char path[1024];
    host_install_fault_handler();
    rt_mem_init();
    rt_sync_register();
    rt_files_register();
    rt_kernel32_register();
    rt_user32_register();
    rt_d3d9_register();
    rt_physx_support_register();
    rt_dinput_register();
    snprintf(path, sizeof path, "%s/..", argv[1]);
    rt_fs_init(path, argc > 3 ? argv[3] : "pc-user");

    RtModule *mods[64], *game = NULL;
    for (int i = 0; i < rt_module_spec_count; i++) {
        const RtModuleSpec *s = &rt_module_specs[i];
        if (!strcmp(s->dir, "game")) snprintf(path, sizeof path, "%s/%s", argv[1], s->file);
        else if (!strcmp(s->dir, "rebased")) snprintf(path, sizeof path, "%s/rebased/%s", argv[2], s->file);
        else snprintf(path, sizeof path, "%s/%s", argv[2], s->file);
        mods[i] = rt_load_module(path, s->name, s->fns, *s->nfns);
        if (!mods[i]->is_dll) game = mods[i];
    }
    for (int i = 0; i < rt_module_spec_count; i++) rt_resolve_imports(mods[i]);
    if (!game) rt_fatal("no executable among the modules");

    RtThread *t = rt_thread_create_main(1u << 20);
    X86Ctx *ctx = &t->ctx;
    st32(rt_peb() + 0x08, game->base); /* PEB.ImageBaseAddress */
    /* Statically imported DLLs run DllMain now, imports first; the rest (PhysXLoader is delay-
       loaded) on their first LoadLibrary. */
    for (int i = 0; i < rt_module_spec_count; i++)
        if (rt_module_specs[i].init_at_start) rt_module_init_tree(mods[i], ctx);
    rt_module_init_tree(game, ctx);

    rt_start_stall_watch();
    extern void rt_ue_start_fov(void);
    rt_ue_start_fov(); /* ME_PC_FOV */
    rt_log("entering the game at %#x", game->entry);
    uint32_t r = rt_call(ctx, game->entry, 0, NULL);
    rt_log("game entry returned %u", r);
    return (int)r;
}
